def camel_to_snake(s: str) -> str:
    result = []
    for i, c in enumerate(s):
        if c.isupper() and i > 0:
            result.append('_')
        result.append(c.lower())
    return ''.join(result)

def word_count(text: str) -> dict:
    words = text.split()
    cleaned = [word.strip('.!?,') for word in words]
    return dict((word, cleaned.count(word)) for word in set(cleaned))

def fizzbuzz(n: int) -> list:
    result = []
    for i in range(1, n+1):
        if i % 3 == 0 and i % 5 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def valid_parens(s: str) -> bool:
    stack = []
    mapping = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    for char in s:
        if char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            stack.append(char)
    return not stack

def chunk(xs: list, k: int) -> list:
    result = []
    for i in range(0, len(xs), k):
        result.append(xs[i:i+k])
    return result

